+// Example: How the edge worker validates sessions without database access
+import { verifySessionToken } from "./src/session-store.ts";
+
+// The edge worker receives a token from the client
+// This token was created by the main service with createSession()
+// Example token: "eyJpZCI6IjEyMzQ1Njc4IiwidXNlcklkIjoiYWxpY2UifQ==.HMAC_SIGNATURE"
+
+export const authMiddleware = (token: string) => {
+  // No database call needed! Just verify the cryptographic signature.
+  const session = verifySessionToken(token);
+
+  if (!session) {
+    return { authenticated: false, error: "Invalid or tampered session" };
+  }
+
+  // Session is valid and was legitimately issued by the main service
+  return {
+    authenticated: true,
+    userId: session.userId,
+    sessionId: session.id,
+  };
+};
+
