+// Verify a signed session token without database access (for edge workers)
+export const verifySessionToken = (token: string): Session | null => {
+  const [encodedData, signature] = token.split(".");
+  if (!encodedData || !signature) return null;
+
+  try {
+    const sessionData = Buffer.from(encodedData, "base64").toString("utf-8");
+    if (!verify(sessionData, signature)) return null;
+
+    const { id, userId } = JSON.parse(sessionData);
+    return { id, userId, revokedAt: null };
+  } catch {
+    return null;
+  }
+};
