+import { createHmac, randomBytes } from "crypto";
+
+// Demonstrate the signed session approach
+const SESSION_SECRET = "dev-secret-key";
+
+const sign = (data: string): string => {
+  return createHmac("sha256", SESSION_SECRET).update(data).digest("base64");
+};
+
+const verify = (data: string, signature: string): boolean => {
+  const expected = sign(data);
+  return expected === signature;
+};
+
+// Create a signed session token
+const sessionId = randomBytes(16).toString("hex");
+const userId = "user123";
+const sessionData = JSON.stringify({ id: sessionId, userId });
+const signature = sign(sessionData);
+const token = `${Buffer.from(sessionData).toString("base64")}.${signature}`;
+
+console.log("✓ Created signed token:", token.substring(0, 50) + "...");
+
+// Verify the token (this is what the edge worker does - no DB needed!)
+const [encodedData, sig] = token.split(".");
+const decoded = Buffer.from(encodedData, "base64").toString("utf-8");
+const isValid = verify(decoded, sig);
+
+console.log("✓ Token verification (edge worker - no DB):", isValid);
+console.log("✓ Decoded session:", JSON.parse(decoded));
+
+// Test with tampered signature
+const tamperedToken = encodedData + ".BADSIGNATURE";
+const [badData, badSig] = tamperedToken.split(".");
+const isTamperedValid = verify(Buffer.from(badData, "base64").toString("utf-8"), badSig);
+console.log("✓ Tampered token rejected:", !isTamperedValid);
